(()=>{'use strict';
const KEY='ccner.level2.profile.v1',AUTH='ccner.level2.auth.v1',OTP='ccner.level2.pendingOtp.v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function load(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}}
function save(k,v){localStorage.setItem(k,JSON.stringify(v))}
function gate(){
 if(document.getElementById('l2AuthGate'))return;
 const g=document.createElement('div');g.id='l2AuthGate';g.innerHTML=`<div class="l2-shell"><div class="l2-brand"><div class="puppy">🐶</div><h1>Welcome to Cognitive Care NER</h1><p>Momo is ready to help you get started.</p></div><div class="l2-card"><div class="l2-progress"><span id="l2p1" class="active"></span><span id="l2p2"></span><span id="l2p3"></span></div><div id="l2err" class="l2-error"></div><section class="l2-step active" data-step="1"><h2>Sign in with your mobile number</h2><p class="hint">We'll use your mobile number to keep your account and progress connected.</p><div class="l2-field"><label for="l2phone">Mobile number</label><input id="l2phone" type="tel" inputmode="numeric" autocomplete="tel" placeholder="10-digit mobile number" maxlength="10"></div><div class="l2-actions"><button class="l2-btn primary" id="l2send">Send OTP</button></div><div class="l2-note">Your personal information is stored securely in this prototype. Do not enter someone else's number.</div></section><section class="l2-step" data-step="2"><h2>Verify your mobile number</h2><p class="hint">Enter the one-time code sent to <span id="l2phoneShow" class="l2-phone"></span>.</p><div class="l2-field"><label for="l2otp">6-digit OTP</label><input id="l2otp" class="l2-otp" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"></div><div class="l2-actions"><button class="l2-btn primary" id="l2verify">Verify & continue</button><button class="l2-btn ghost" id="l2back">Change number</button></div><div id="l2demo" class="l2-note" hidden></div></section><section class="l2-step" data-step="3"><h2>Let's create your profile</h2><p class="hint">A few details help Momo personalize the experience. Optional information can be skipped and completed later.</p><div class="l2-grid"><div class="l2-field"><label for="l2name">Full name</label><input id="l2name" autocomplete="name" placeholder="Full name" required></div><div class="l2-field"><label for="l2dob">Date of birth</label><input id="l2dob" type="date" autocomplete="bday" required></div><div class="l2-field"><label for="l2age">Age</label><input id="l2age" readonly placeholder="Calculated automatically"></div><div class="l2-field"><label for="l2gender">Gender</label><select id="l2gender"><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option><option>Prefer not to say</option></select></div><div class="l2-field"><label for="l2role">Role</label><select id="l2role"><option value="patient">Patient</option><option value="caregiver">Caregiver</option><option value="health_worker">Doctor / Health Worker</option></select></div><div class="l2-field"><label for="l2lang">Preferred language</label><select id="l2lang"><option value="en">English</option><option value="hi">Hindi</option><option value="bn">Bengali</option><option value="as">Assamese</option></select></div></div><div class="l2-optional"><h3>Optional information</h3><div class="l2-grid"><div class="l2-field"><label for="l2email">Email</label><input id="l2email" type="email" autocomplete="email" placeholder="name@example.com"></div><div class="l2-field"><label for="l2photo">Profile photo</label><input id="l2photo" type="file" accept="image/*"></div><div class="l2-field"><label for="l2emergency">Emergency contact</label><input id="l2emergency" type="tel" placeholder="Mobile number"></div><div class="l2-field"><label for="l2relationship">Relationship</label><input id="l2relationship" placeholder="e.g. Daughter, son, spouse"></div><div class="l2-field"><label for="l2momoname">Momo name</label><input id="l2momoname" placeholder="Momo"></div><div class="l2-field"><label for="l2voice">Voice preference</label><select id="l2voice"><option value="default">Default</option><option value="slow">Slower</option><option value="loud">Louder</option></select></div><div class="l2-field"><label for="l2region">Region</label><input id="l2region" placeholder="State / district / NER region"></div><div class="l2-field"><label for="l2access">Accessibility preference</label><input id="l2access" placeholder="Large text, high contrast, etc."></div></div></div><div class="l2-actions"><button class="l2-btn primary" id="l2save">Save profile & enter app</button><button class="l2-btn secondary" id="l2skip">Skip optional information & enter app</button></div></section></div></div>`;document.body.prepend(g);
 const app=document.querySelector('.app-shell');if(app)app.style.display='none';
 const err=(m)=>{const e=document.getElementById('l2err');e.textContent=m;e.classList.toggle('show',!!m)};
 const step=n=>{g.querySelectorAll('.l2-step').forEach(x=>x.classList.toggle('active',x.dataset.step==n));[1,2,3].forEach(i=>document.getElementById('l2p'+i).classList.toggle('active',i<=n));err('')};
 const phone=()=>document.getElementById('l2phone').value.replace(/\D/g,'');
 const age=dob=>{const d=new Date(dob+'T00:00:00'),now=new Date();if(!dob||isNaN(d))return '';let a=now.getFullYear()-d.getFullYear();if(now.getMonth()<d.getMonth()||(now.getMonth()===d.getMonth()&&now.getDate()<d.getDate()))a--;return a>=0&&a<130?a:''};
 document.getElementById('l2send').onclick=()=>{const p=phone();if(!/^[6-9]\d{9}$/.test(p))return err('Please enter a valid 10-digit Indian mobile number.');const code=String(Math.floor(100000+Math.random()*900000));save(OTP,{phone:p,code,expires:Date.now()+5*60*1000});document.getElementById('l2phoneShow').textContent='+91 '+p;const demo=document.getElementById('l2demo');demo.hidden=false;demo.textContent='Prototype verification: OTP '+code+' is ready for this demo. In production, connect this flow to your approved SMS/OTP provider.';step(2)};
 document.getElementById('l2back').onclick=()=>step(1);
 document.getElementById('l2verify').onclick=()=>{const x=load(OTP),v=document.getElementById('l2otp').value.trim();if(!x||Date.now()>x.expires)return err('This OTP has expired. Please request a new one.');if(v!==x.code)return err('Incorrect OTP. Please check the code and try again.');save(AUTH,{phone:x.phone,verifiedAt:new Date().toISOString()});localStorage.removeItem(OTP);step(3)};
 document.getElementById('l2dob').onchange=e=>document.getElementById('l2age').value=age(e.target.value);
 const finish=async skip=>{const name=document.getElementById('l2name').value.trim(),dob=document.getElementById('l2dob').value;if(!name||!dob)return err('Please enter your full name and date of birth.');const a=age(dob);if(!a)return err('Please enter a valid date of birth.');let photo='';const f=document.getElementById('l2photo').files[0];if(f){if(f.size>1024*1024)return err('Profile photo must be 1 MB or smaller.');photo=await new Promise(r=>{const rd=new FileReader();rd.onload=()=>r(rd.result);rd.readAsDataURL(f)})}const p={phone:load(AUTH)?.phone||'',fullName:name,dob,age:a,gender:document.getElementById('l2gender').value,role:document.getElementById('l2role').value,language:document.getElementById('l2lang').value,email:skip?'':document.getElementById('l2email').value.trim(),photo,emergencyContact:skip?'':document.getElementById('l2emergency').value.trim(),relationship:skip?'':document.getElementById('l2relationship').value.trim(),momoName:skip?'Momo':(document.getElementById('l2momoname').value.trim()||'Momo'),voicePreference:skip?'default':document.getElementById('l2voice').value,region:skip?'':document.getElementById('l2region').value.trim(),accessibility:skip?'':document.getElementById('l2access').value.trim(),updatedAt:new Date().toISOString()};save(KEY,p);save(AUTH,{...load(AUTH),profileComplete:true});g.remove();if(app)app.style.display='';window.dispatchEvent(new CustomEvent('ccner:profile-ready',{detail:p}))};
 document.getElementById('l2save').onclick=()=>finish(false);document.getElementById('l2skip').onclick=()=>finish(true);
}
function boot(){const p=load(KEY),a=load(AUTH);if(p&&a?.verified&&a?.profileComplete)return;gate()}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
window.CCNERAuth={getProfile:()=>load(KEY),isAuthenticated:()=>!!(load(KEY)&&load(AUTH)?.verified&&load(AUTH)?.profileComplete),logout:()=>{localStorage.removeItem(KEY);localStorage.removeItem(AUTH);location.reload()}};
})();